Dataspatium.assets.register("presets/api/worldbank.api.json","text","{\n \"format\": \"dataspatium-api/1\",\n \"id\": \"worldbank\",\n \"name\": \"Världsbanken: indikatorer (World Development Indicators)\",\n \"publisher\": \"Världsbanken\",\n \"description\": \"Världsbankens indikatorer för länder och år, till exempel folkmängd, BNP och koldioxidutsläpp: en rad per land och år med indikatorns värde.\",\n \"docs\": \"https://datahelpdesk.worldbank.org/knowledgebase/articles/889392\",\n \"license\": {\n  \"name\": \"CC BY 4.0\",\n  \"url\": \"https://datacatalog.worldbank.org/public-licenses\"\n },\n \"level\": 1,\n \"country\": \"INT\",\n \"baseUrl\": \"https://api.worldbank.org/v2\",\n \"auth\": {\n  \"type\": \"none\"\n },\n \"rateLimit\": {\n  \"requests\": 2,\n  \"perSeconds\": 1\n },\n \"cors\": {\n  \"file\": false,\n  \"web\": false\n },\n \"endpoints\": [\n  {\n   \"id\": \"indikator\",\n   \"name\": \"En indikator för länder\",\n   \"description\": \"Indikatorns värden per land och år; länderna avgränsas med semikolon.\",\n   \"method\": \"GET\",\n   \"path\": \"/country/{country}/indicator/{indicator}\",\n   \"params\": [\n    {\n     \"name\": \"country\",\n     \"in\": \"path\",\n     \"label\": \"Länder (ISO-koder)\",\n     \"type\": \"string\",\n     \"required\": true,\n     \"raw\": true,\n     \"default\": \"SE;NO;DK;FI;IS\",\n     \"example\": \"SE;NO;DK;FI;IS\"\n    },\n    {\n     \"name\": \"indicator\",\n     \"in\": \"path\",\n     \"label\": \"Indikator\",\n     \"type\": \"string\",\n     \"required\": true,\n     \"default\": \"SP.POP.TOTL\",\n     \"example\": \"NY.GDP.MKTP.CD\",\n     \"help\": \"SP.POP.TOTL folkmängd, NY.GDP.MKTP.CD BNP i US-dollar, EN.GHG.CO2.MT.CE.AR5 koldioxid.\"\n    },\n    {\n     \"name\": \"date\",\n     \"in\": \"query\",\n     \"label\": \"År\",\n     \"type\": \"string\",\n     \"example\": \"2000:2024\",\n     \"help\": \"Ett år eller ett intervall, till exempel 2000:2024.\"\n    },\n    {\n     \"name\": \"format\",\n     \"in\": \"query\",\n     \"type\": \"string\",\n     \"default\": \"json\",\n     \"hidden\": true\n    },\n    {\n     \"name\": \"per_page\",\n     \"in\": \"query\",\n     \"type\": \"number\",\n     \"default\": 1000,\n     \"hidden\": true\n    }\n   ],\n   \"pagination\": {\n    \"type\": \"page\",\n    \"param\": \"page\",\n    \"start\": 1,\n    \"totalPagesPath\": \"0.pages\",\n    \"maxPages\": 50\n   },\n   \"response\": {\n    \"format\": \"json\",\n    \"path\": \"1\"\n   },\n   \"dataset\": {\n    \"name\": \"Världsbanken {indicator}\"\n   }\n  }\n ],\n \"notes\": \"Tjänsten tillåter inte anrop från webbläsaren (ingen CORS), så den nås bara via bryggan: starta bryggan med --allow-host api.worldbank.org (-AllowHosts api.worldbank.org i PowerShell), anslut den under Inhämta och slå på Hämta via bryggan i Internetåtkomst.\",\n \"i18n\": {\n  \"en\": {\n   \"name\": \"World Bank: indicators (World Development Indicators)\",\n   \"publisher\": \"World Bank\",\n   \"description\": \"The World Bank’s indicators for countries and years, such as population, GDP and carbon dioxide emissions: one row per country and year with the indicator’s value.\",\n   \"notes\": \"The service does not allow requests from the browser (no CORS), so it is reached only through the bridge: start the bridge with --allow-host api.worldbank.org (-AllowHosts api.worldbank.org in PowerShell), connect it under Import and turn on Fetch through the bridge in Internet access.\",\n   \"endpoints\": {\n    \"indikator\": {\n     \"name\": \"One indicator for countries\",\n     \"params\": {\n      \"country\": {\n       \"label\": \"Countries (ISO codes)\"\n      },\n      \"indicator\": {\n       \"label\": \"Indicator\",\n       \"help\": \"SP.POP.TOTL population, NY.GDP.MKTP.CD GDP in US dollars, EN.GHG.CO2.MT.CE.AR5 carbon dioxide.\"\n      },\n      \"date\": {\n       \"label\": \"Year\",\n       \"help\": \"One year or a range, for example 2000:2024.\"\n      }\n     }\n    }\n   }\n  },\n  \"da\": {\n   \"name\": \"Verdensbanken: indikatorer (World Development Indicators)\",\n   \"publisher\": \"Verdensbanken\",\n   \"description\": \"Verdensbankens indikatorer for lande og år, for eksempel befolkning, BNP og CO2-udledning: én række pr. land og år med indikatorens værdi.\",\n   \"notes\": \"Tjenesten tillader ikke kald fra browseren (ingen CORS), så den nås kun via broen: start broen med --allow-host api.worldbank.org (-AllowHosts api.worldbank.org i PowerShell), forbind den under Hent, og slå Hent via broen til under Internetadgang.\",\n   \"endpoints\": {\n    \"indikator\": {\n     \"name\": \"Én indikator for lande\",\n     \"params\": {\n      \"country\": {\n       \"label\": \"Lande (ISO-koder)\"\n      },\n      \"indicator\": {\n       \"label\": \"Indikator\",\n       \"help\": \"SP.POP.TOTL befolkning, NY.GDP.MKTP.CD BNP i US-dollar, EN.GHG.CO2.MT.CE.AR5 CO2.\"\n      },\n      \"date\": {\n       \"label\": \"År\",\n       \"help\": \"Et år eller et interval, for eksempel 2000:2024.\"\n      }\n     }\n    }\n   }\n  },\n  \"nb\": {\n   \"name\": \"Verdensbanken: indikatorer (World Development Indicators)\",\n   \"publisher\": \"Verdensbanken\",\n   \"description\": \"Verdensbankens indikatorer for land og år, for eksempel folketall, BNP og CO2-utslipp: én rad per land og år med indikatorens verdi.\",\n   \"notes\": \"Tjenesten tillater ikke kall fra nettleseren (ingen CORS), så den nås bare via broen: start broen med --allow-host api.worldbank.org (-AllowHosts api.worldbank.org i PowerShell), koble den til under Hent inn og slå på Hent via broen under Internettilgang.\",\n   \"endpoints\": {\n    \"indikator\": {\n     \"name\": \"Én indikator for land\",\n     \"params\": {\n      \"country\": {\n       \"label\": \"Land (ISO-koder)\"\n      },\n      \"indicator\": {\n       \"label\": \"Indikator\",\n       \"help\": \"SP.POP.TOTL folketall, NY.GDP.MKTP.CD BNP i US-dollar, EN.GHG.CO2.MT.CE.AR5 CO2.\"\n      },\n      \"date\": {\n       \"label\": \"År\",\n       \"help\": \"Ett år eller et intervall, for eksempel 2000:2024.\"\n      }\n     }\n    }\n   }\n  },\n  \"nn\": {\n   \"name\": \"Verdsbanken: indikatorar (World Development Indicators)\",\n   \"publisher\": \"Verdsbanken\",\n   \"description\": \"Indikatorane til Verdsbanken for land og år, til dømes folketal, BNP og CO2-utslepp: éi rad per land og år med verdien til indikatoren.\",\n   \"notes\": \"Tenesta tillèt ikkje kall frå nettlesaren (ingen CORS), så ho blir berre nådd via brua: start brua med --allow-host api.worldbank.org (-AllowHosts api.worldbank.org i PowerShell), kople ho til under Hent og slå på Hent via brua under Internettilgang.\",\n   \"endpoints\": {\n    \"indikator\": {\n     \"name\": \"Éin indikator for land\",\n     \"params\": {\n      \"country\": {\n       \"label\": \"Land (ISO-kodar)\"\n      },\n      \"indicator\": {\n       \"label\": \"Indikator\",\n       \"help\": \"SP.POP.TOTL folketal, NY.GDP.MKTP.CD BNP i US-dollar, EN.GHG.CO2.MT.CE.AR5 CO2.\"\n      },\n      \"date\": {\n       \"label\": \"År\",\n       \"help\": \"Eitt år eller eit intervall, til dømes 2000:2024.\"\n      }\n     }\n    }\n   }\n  },\n  \"fi\": {\n   \"name\": \"Maailmanpankki: indikaattorit (World Development Indicators)\",\n   \"publisher\": \"Maailmanpankki\",\n   \"description\": \"Maailmanpankin indikaattorit maittain ja vuosittain, esimerkiksi väkiluku, BKT ja hiilidioksidipäästöt: yksi rivi maata ja vuotta kohden indikaattorin arvolla.\",\n   \"notes\": \"Palvelu ei salli kutsuja selaimesta (ei CORSia), joten sen tavoittaa vain sillan kautta: käynnistä silta valinnalla --allow-host api.worldbank.org (PowerShellissä -AllowHosts api.worldbank.org), yhdistä se kohdassa Tuo ja kytke Hae sillan kautta päälle kohdassa Internetyhteys.\",\n   \"endpoints\": {\n    \"indikator\": {\n     \"name\": \"Yksi indikaattori maille\",\n     \"params\": {\n      \"country\": {\n       \"label\": \"Maat (ISO-koodit)\"\n      },\n      \"indicator\": {\n       \"label\": \"Indikaattori\",\n       \"help\": \"SP.POP.TOTL väkiluku, NY.GDP.MKTP.CD BKT Yhdysvaltain dollareina, EN.GHG.CO2.MT.CE.AR5 hiilidioksidi.\"\n      },\n      \"date\": {\n       \"label\": \"Vuosi\",\n       \"help\": \"Yksi vuosi tai väli, esimerkiksi 2000:2024.\"\n      }\n     }\n    }\n   }\n  },\n  \"is\": {\n   \"name\": \"Alþjóðabankinn: vísar (World Development Indicators)\",\n   \"publisher\": \"Alþjóðabankinn\",\n   \"description\": \"Vísar Alþjóðabankans fyrir lönd og ár, til dæmis mannfjöldi, verg landsframleiðsla og koltvísýringslosun: ein röð fyrir hvert land og ár með gildi vísisins.\",\n   \"notes\": \"Þjónustan leyfir ekki köll úr vafranum (ekkert CORS), svo hún næst aðeins um brúna: ræstu brúna með --allow-host api.worldbank.org (-AllowHosts api.worldbank.org í PowerShell), tengdu hana undir Sækja og kveiktu á Sækja um brúna undir Netaðgangur.\",\n   \"endpoints\": {\n    \"indikator\": {\n     \"name\": \"Einn vísir fyrir lönd\",\n     \"params\": {\n      \"country\": {\n       \"label\": \"Lönd (ISO-kóðar)\"\n      },\n      \"indicator\": {\n       \"label\": \"Vísir\",\n       \"help\": \"SP.POP.TOTL mannfjöldi, NY.GDP.MKTP.CD VLF í Bandaríkjadölum, EN.GHG.CO2.MT.CE.AR5 koltvísýringur.\"\n      },\n      \"date\": {\n       \"label\": \"Ár\",\n       \"help\": \"Eitt ár eða bil, til dæmis 2000:2024.\"\n      }\n     }\n    }\n   }\n  }\n }\n}\n");
